/**
 * Differential parity with crates/noised-rules: the crate's
 * tests/differential.rs and ./differential.ts generate the same seeded
 * programs; the crate commits one entry per case (vectors/differential.json)
 * and the SDK must reproduce every entry exactly — the generated bytes, the
 * verifier's verdict (hash or error name), the layout parser's verdict, and
 * the digest of every evaluation, condition, schedule, cap, epoch, share,
 * threshold and codec round trip (see differential.ts).
 *
 * `NOISED_DIFF_FILE=<file>` also runs a larger file written by the crate
 * (`NOISED_DIFF_OUT=<file> NOISED_DIFF_CASES=<n> cargo test -p noised-rules --test differential`).
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

import { compileGraph, compileRules, decompileGraph, decompileRules, NOT_DUE, ProgError, toHex, VERIFY_ERRORS } from "../../src/programmable/index.js";
import {
  FORMAT,
  GRAPH_SEED,
  RULES_SEED,
  Rng,
  SAMPLES,
  entry,
  genGraphCase,
  genRulesCase,
  graphLine,
  rulesLine,
  type GraphCase,
  type RulesCase,
} from "./differential.js";
import { loadVectors } from "./vectorFiles.js";

/* eslint-disable @typescript-eslint/no-explicit-any */
type J = any;

interface Mismatch {
  case: number;
  want: string;
  got: string;
  line: string;
}

/** Case i of a format: SplitMix64 seeded with seed + i (generated once per run). */
function cases<C>(gen: (rng: Rng) => C, seed: bigint): (i: number) => C {
  const memo: C[] = [];
  return (i) => (memo[i] ??= gen(new Rng(seed + BigInt(i))));
}
const rulesCase = cases<RulesCase>(genRulesCase, RULES_SEED);
const graphCase = cases<GraphCase>(genGraphCase, GRAPH_SEED);

/** Compares every entry; returns the first few mismatches with the SDK's full line. */
function compare(kind: "rules" | "graph", entries: readonly string[], at: (i: number) => RulesCase | GraphCase): Mismatch[] {
  const mismatches: Mismatch[] = [];
  entries.forEach((want, i) => {
    const c = at(i);
    const line = kind === "rules" ? rulesLine(c as RulesCase) : graphLine(c as GraphCase);
    const got = entry(c.bytes, line);
    if (got !== want && mismatches.length < 8) {
      const hint = got.split(" ")[0] === want.split(" ")[0] ? `crate line: NOISED_DIFF_DUMP=${kind}:${i}` : "the generators drifted";
      mismatches.push({ case: i, want, got, line: `${line.length > 600 ? `${line.slice(0, 600)}…` : line} (${hint})` });
    }
  });
  return mismatches;
}

function checkHeader(file: J, kind: "rules" | "graph"): void {
  expect(file.format).toBe(FORMAT);
  expect(BigInt(file[kind].seed)).toBe(kind === "rules" ? RULES_SEED : GRAPH_SEED);
  expect(file[kind].samples).toBe(SAMPLES);
}

describe("differential parity with the crate (DIFF1)", () => {
  const file = loadVectors("differential.json");

  it("the file is the crate's DIFF1 run", () => {
    checkHeader(file, "rules");
    checkHeader(file, "graph");
    expect(file.rules.cases.length).toBeGreaterThanOrEqual(3_000);
    expect(file.graph.cases.length).toBeGreaterThanOrEqual(3_000);
    // A quarter or more of each verifies (and is evaluated in full); the rest
    // covers the errors (counts by name, as the crate saw them).
    expect(file.rules.verify.ok * 4).toBeGreaterThanOrEqual(file.rules.cases.length);
    expect(file.graph.verify.ok * 4).toBeGreaterThanOrEqual(file.graph.cases.length);
    expect(Object.keys(file.rules.verify).length).toBeGreaterThanOrEqual(30);
    expect(Object.keys(file.graph.verify).length).toBeGreaterThanOrEqual(44);
  });

  it("error and not-due names are the crate's, in discriminant order", () => {
    expect([...VERIFY_ERRORS]).toEqual(file.names.errors);
    expect([...NOT_DUE]).toEqual(file.names.not_due);
  });

  it("PXR1: every case matches the crate (bytes, verdicts, evaluation, conditions, thresholds)", () => {
    expect(compare("rules", file.rules.cases, rulesCase)).toEqual([]);
  });

  it("PXG1: every case matches the crate (bytes, verdicts, schedule, conditions, caps, epochs, shares)", () => {
    expect(compare("graph", file.graph.cases, graphCase)).toEqual([]);
  });

  it("the SDK's verdict counts are the crate's", () => {
    const tally = (entries: readonly string[]): Record<string, number> => {
      const out: Record<string, number> = {};
      for (const e of entries) {
        const v = e.split(" ")[1]!;
        out[v] = (out[v] ?? 0) + 1;
      }
      return out;
    };
    expect(tally(file.rules.cases)).toEqual(file.rules.verify);
    expect(tally(file.graph.cases)).toEqual(file.graph.verify);
  });

  // The same programs through the model layer: every rule set / graph the
  // crate accepts decompiles to a model that compiles back to the same bytes
  // (or the model refuses it with BadModel, never a different encoding).
  it("PXR1: verified cases round-trip through the model", () => {
    let roundTrips = 0;
    file.rules.cases.forEach((e: string, i: number) => {
      if (e.split(" ")[1] !== "ok") return;
      const c = rulesCase(i);
      try {
        expect(toHex(compileRules(decompileRules(c.bytes, { guardSecs: Math.min(c.guard, 259_200) })))).toBe(toHex(c.bytes));
        roundTrips++;
      } catch (err) {
        if (!(err instanceof ProgError) || err.code !== "BadModel") throw err;
      }
    });
    expect(roundTrips).toBeGreaterThan(file.rules.verify.ok / 2);
  });

  it("PXG1: verified cases round-trip through the model", () => {
    let roundTrips = 0;
    file.graph.cases.forEach((e: string, i: number) => {
      if (e.split(" ")[1] !== "ok") return;
      const c = graphCase(i);
      try {
        expect(toHex(compileGraph(decompileGraph(c.bytes)))).toBe(toHex(c.bytes));
        roundTrips++;
      } catch (err) {
        if (!(err instanceof ProgError) || err.code !== "BadModel") throw err;
      }
    });
    expect(roundTrips).toBeGreaterThan(file.graph.verify.ok / 2);
  });
});

const big = (process.env["NOISED_DIFF_FILE"] ?? process.env["PHALANX_DIFF_FILE"]);
describe.skipIf(!big)("differential parity: larger crate run ($NOISED_DIFF_FILE)", () => {
  const file: J = big ? JSON.parse(readFileSync(big, "utf8")) : null;
  // No memo here: the larger runs would hold every case in memory.
  const fresh = <C>(gen: (rng: Rng) => C, seed: bigint) => (i: number): C => gen(new Rng(seed + BigInt(i)));
  it("PXR1", () => {
    checkHeader(file, "rules");
    expect(compare("rules", file.rules.cases, fresh(genRulesCase, RULES_SEED))).toEqual([]);
  }, 3_600_000);
  it("PXG1", () => {
    checkHeader(file, "graph");
    expect(compare("graph", file.graph.cases, fresh(genGraphCase, GRAPH_SEED))).toEqual([]);
  }, 3_600_000);
});
